<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#153c3e"><title>Cat Supper Club</title>
<style>
:root{--ink:#153c3e;--paper:#fff1d6;--orange:#ee9b51;--muted:#a8c2bc;--line:#386061}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--paper);font-family:Palatino,"Book Antiqua",serif;font-size:18px;line-height:1.5}button,select{font:inherit}button,a,select{-webkit-tap-highlight-color:transparent}button{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #f9c171;outline-offset:5px}a{color:inherit;text-underline-offset:4px}main{max-width:1150px;margin:auto;padding:28px 30px 45px}.top{display:flex;justify-content:space-between;gap:20px;font:12px "Courier New",monospace;letter-spacing:.12em;text-transform:uppercase}.hero{display:grid;grid-template-columns:.86fr 1.14fr;gap:38px;align-items:center;margin:38px 0}.eyebrow{font:12px "Courier New",monospace;text-transform:uppercase;letter-spacing:.2em;color:var(--orange)}h1{font-weight:400;font-size:clamp(58px,7.8vw,100px);line-height:.91;letter-spacing:-.065em;margin:20px 0 25px}h1 em{color:var(--orange)}.intro{max-width:360px;color:#d4dfcf;font-size:19px}.hero figure{margin:0;transform:rotate(1.5deg);background:var(--paper);padding:10px 10px 0;box-shadow:10px 12px 0 #092b2d}.hero img{display:block;width:100%;aspect-ratio:3/2;object-fit:cover}.legend{display:grid;grid-template-columns:repeat(4,1fr);text-align:center;color:var(--ink);padding:12px 0;font-size:13px;gap:3px}.legend small{display:block;font-size:10px;font-family:"Courier New",monospace}.game{background:var(--paper);color:var(--ink);padding:30px;position:relative;box-shadow:0 8px 0 #0b2e30}.game:before{content:"";position:absolute;top:-8px;left:0;width:100%;height:8px;background:repeating-linear-gradient(90deg,var(--paper) 0 12px,transparent 12px 18px)}.gamehead{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border-bottom:1px solid #cdbf9e;padding-bottom:15px}.gamehead>div{min-width:0;max-width:100%}.gamehead label{font:12px "Courier New",monospace;text-transform:uppercase}select{background:transparent;color:var(--ink);border:1px solid #897c60;border-radius:0;max-width:100%;padding:8px;font-size:16px}h2{font-size:32px;line-height:1.1;font-weight:400;margin:0}.split{display:grid;grid-template-columns:1fr 1.3fr;gap:35px;margin-top:20px}.number{font:11px "Courier New",monospace;letter-spacing:.1em;text-transform:uppercase}.clues{padding-left:24px;font-size:18px}.clues li{padding:8px 5px;border-bottom:1px dotted #b9ad91}.clues li.good{color:#24654c}.clues li.bad{background:#f8dac2}.clues li.hinted{outline:2px dashed #a05227}.directions{font-size:16px;margin-top:0}.cats{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:15px 0}.cat{background:#eedfbd;color:var(--ink);border:1px solid #b0a282;padding:10px 2px;min-height:76px;font-size:13px;line-height:1.3;position:relative}.cat[aria-pressed=true]{background:var(--ink);color:var(--paper);border-color:var(--ink);box-shadow:0 4px 0 var(--orange);transform:translateY(-3px)}.cat.used:after{content:"seated";display:block;font-size:10px;font-family:"Courier New",monospace;margin-top:4px}.face{display:block;margin:auto auto 6px;width:30px;height:26px;border-radius:40% 40% 45% 45%;background:var(--fur);border:1px solid #776b57;position:relative;box-shadow:inset 0 -6px 0 var(--bib)}.face:before{content:"";position:absolute;inset:-5px 1px 8px;background:var(--fur);clip-path:polygon(0 0,35% 25%,65% 25%,100% 0,95% 100%,5% 100%)}.face:after{content:"• •";font:bold 17px Georgia,serif;color:var(--eyes);position:absolute;left:5px;top:0;white-space:pre}.seats{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;border-top:4px solid #bb6c3d;border-bottom:8px solid #bb6c3d;padding:14px 0;background:#efdcb7}.seat{min-height:116px;background:transparent;border:1px dashed #a89067;color:var(--ink);padding:6px 1px;font-size:13px}.seat .bowl{display:block;width:42px;height:18px;border-radius:3px 3px 50% 50%;border:2px solid #9b5a37;background:#e5a66b;margin:8px auto}.seat strong{display:block;font-size:13px;min-height:24px}.seat small{font:10px "Courier New",monospace;display:block}.axis{display:flex;justify-content:space-between;font:11px "Courier New",monospace;margin-top:6px}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:23px}button.action{border:1px solid var(--ink);background:transparent;color:var(--ink);padding:10px 16px;min-height:45px;font-size:16px}button.primary{background:var(--ink);color:var(--paper)}button:disabled{opacity:.45;cursor:default}.message{min-height:70px;padding:15px 0 0;font-size:17px}.message strong{color:#27624a}.utilities{border-top:1px solid #cdbf9e;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-top:12px;font:12px "Courier New",monospace}.textbutton{border:0;background:none;text-decoration:underline;color:var(--ink);padding:8px 0;font-size:13px}.progress{font-size:13px;color:var(--muted);margin:20px 0}.progress span{color:var(--orange);letter-spacing:.25em}footer{margin-top:30px;color:#b9cfbf;font-size:14px;max-width:720px}footer p{margin:10px 0}.celebrate .bowl{animation:hop .55s ease-in-out 2}@keyframes hop{50%{transform:translateY(-8px) rotate(-8deg)}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}@media(max-width:760px){main{padding:20px 18px 35px}.hero{grid-template-columns:1fr;gap:24px;margin:30px 0 38px}h1{font-size:72px}.intro{max-width:100%}.hero figure{max-width:540px}.split{grid-template-columns:1fr;gap:18px}.game{padding:23px 18px}.clues{margin:10px 0}.top{font-size:10px}.gamehead{align-items:start}.cats{gap:5px}.legend{font-size:12px}.legend small{font-size:9px}}@media(max-width:360px){main{padding-inline:12px}.game{padding-inline:12px}h1{font-size:62px}.seat{font-size:12px}.cat{font-size:12px}}
</style></head><body><main>
<nav class="top"><a href="./">← Chloe reads Jon</a><span>Open nightly · No reservations</span></nav>
<header class="hero"><div><div class="eyebrow">A small mystery, served warm</div><h1>Cat<br><em>Supper</em><br>Club.</h1><p class="intro">Four cats. Four places. Quite a few opinions. Can you seat tonight’s regulars using nothing but their clues?</p></div>
<figure><img id="art" src="?art=1" alt="The supper club regulars: Pepper the black cat, Marmalade the ginger tabby, Cloud the white cat, and Socks the tuxedo cat."><figcaption class="legend"><span>Pepper<small>black coat</small></span><span>Marmalade<small>ginger tabby</small></span><span>Cloud<small>white fluff</small></span><span>Socks<small>tuxedo &amp; paws</small></span></figcaption></figure></header>
<section class="game" aria-label="Cat seating puzzle">
<div class="gamehead"><div><p class="number" id="nightLabel">Night 01 / 05</p><h2 id="title">The usual table</h2></div><div><label for="night">Choose a night</label><br><select id="night"></select></div></div>
<div class="split"><section><div class="number">The maître d’s notes</div><ol id="clues" class="clues"></ol><p style="font-size:14px">“Next to” means immediately beside. Left and right are <em>your</em> left and right. Every cat gets one place.</p></section>
<section aria-label="Arrange the table"><p class="directions"><b>1.</b> Pick a cat. <b>2.</b> Tap a place.<br>Moving onto another cat swaps their places. Tap an occupied place with no cat selected to lift that cat out.</p><div id="cats" class="cats" aria-label="Choose a cat"></div><div id="seats" class="seats" aria-label="Seats from left to right"></div><div class="axis"><span>← LEFT / WINDOW</span><span>DOOR / RIGHT →</span></div><div class="actions"><button class="action primary" id="check">Ring the dinner bell</button><button class="action" id="hint">A little hint</button><button class="action" id="next" hidden>Next night →</button></div><div id="message" class="message" role="status" aria-live="polite">The regulars are waiting. No timer, no score, no rush.</div></section></div>
<div class="utilities"><button class="textbutton" id="reset">Clear this table</button><button class="textbutton" id="reveal">Show this night’s arrangement</button><span id="served"></span></div></section>
<p class="progress"><span id="dots">○ ○ ○ ○ ○</span> &nbsp; Five evenings at the same little counter.</p>
<footer><p>Inspired by Jon’s <a href="?source=1">“Jon’s nightly cat-feeding ritual”</a> (November 16, 2004). His photo-post supplied the spark; these four demanding regulars and their dinner mysteries are invented.</p><p>Original illustrated cast · A tiny after-dinner deduction game for Jon &amp; Nathan.</p></footer><noscript><p>This supper club needs JavaScript to arrange its cats.</p></noscript>
</main><script>
'use strict';
const names=['Pepper','Marmalade','Cloud','Socks'];
const colors=[['#23272a','#23272a','#e7bf58'],['#d78d47','#e3ac6d','#263f38'],['#fffaf0','#fffaf0','#526e77'],['#23272a','#fffaf0','#dbbe6a']];
const nights=[
{title:'The usual table',clues:[['at',0,0,'Pepper sits at the window (place 1).'],['adj',1,0,'Marmalade sits next to Pepper.'],['left',1,2,'Cloud sits somewhere to the right of Marmalade.'],['at',3,3,'Socks sits at the door (place 4).']]},
{title:'A change of scenery',clues:[['notend',2,0,'Cloud will not sit at either end.'],['immediate',3,2,'Socks sits immediately to the left of Cloud.'],['left',2,0,'Pepper sits somewhere to the right of Cloud.'],['left',1,3,'Marmalade sits somewhere to the left of Socks.']]},
{title:'The long-distance stare',clues:[['gap3',0,2,'There are exactly two cats between Pepper and Cloud.'],['left',2,0,'Cloud sits somewhere to the left of Pepper.'],['immediate',3,1,'Marmalade sits immediately to the right of Socks.']]},
{title:'An extremely particular evening',clues:[['notend',1,0,'Marmalade refuses both end places.'],['adj',0,1,'Pepper sits next to Marmalade.'],['immediate',0,2,'Cloud sits immediately to the right of Pepper.'],['left',3,1,'Socks sits somewhere to the left of Marmalade.']]},
{title:'The midnight committee',clues:[['notend',0,0,'Pepper does not sit at either end.'],['notend',3,0,'Socks does not sit at either end.'],['left',1,0,'Marmalade sits somewhere to the left of Pepper.'],['gap2',2,0,'Exactly one cat sits between Cloud and Pepper.'],['adj',3,2,'Socks sits next to Cloud.']]}
];
const $=id=>document.getElementById(id);
let current=0,board=[null,null,null,null],selected=null,checked=false,solved=false,revealed=false;
const completed=new Set();
function meets(b,c){const [op,a,d]=c,x=b.indexOf(a),y=b.indexOf(d);if(x<0)return false;if(!['at','notat','notend'].includes(op)&&y<0)return false;switch(op){case'at':return x===d;case'notend':return x>0&&x<3;case'notat':return x!==d;case'adj':return Math.abs(x-y)===1;case'left':return x<y;case'immediate':return x+1===y;case'gap2':return Math.abs(x-y)===2;case'gap3':return Math.abs(x-y)===3;}return false;}
function permute(a){return a.length?a.flatMap((x,i)=>permute(a.filter((_,j)=>j!==i)).map(p=>[x,...p])):[[]];}
function solution(n){return permute([0,1,2,3]).filter(b=>nights[n].clues.every(c=>meets(b,c)));}
function face(id){return '<span class="face" aria-hidden="true" style="--fur:'+colors[id][0]+';--bib:'+colors[id][1]+';--eyes:'+colors[id][2]+'"></span>';}
function say(s){$('message').textContent=s;}
function draw(){
 $('cats').innerHTML=names.map((n,i)=>'<button class="cat '+(board.includes(i)?'used':'')+'" data-cat="'+i+'" aria-pressed="'+(selected===i)+'" aria-label="Select '+n+'">'+face(i)+n+'</button>').join('');
 $('seats').innerHTML=board.map((c,i)=>'<button class="seat" data-seat="'+i+'" aria-label="Place '+(i+1)+', '+(c===null?'empty':names[c])+'. '+(selected===null?'Lift cat':'Seat '+names[selected])+'"><small>PLACE '+(i+1)+'</small><strong>'+(c===null?'Empty':names[c])+'</strong>'+(c===null?'<span style="display:block;height:32px" aria-hidden="true">·</span>':face(c))+'<span class="bowl" aria-hidden="true"></span></button>').join('');
 $('clues').innerHTML=nights[current].clues.map((c,i)=>'<li id="clue'+i+'" class="'+(checked?(meets(board,c)?'good':'bad'):'')+'">'+(checked?(meets(board,c)?'✓ ':'↻ '):'')+c[3]+'</li>').join('');
 $('dots').textContent=nights.map((_,i)=>completed.has(i)?'●':'○').join(' ');
 $('served').textContent=completed.size+' / 5 evenings solved';
 $('next').hidden=!solved||current===4;$('check').disabled=solved;
 $('seats').classList.toggle('celebrate',solved&&!revealed);
}
function load(n){current=n;board=[null,null,null,null];selected=null;checked=false;solved=false;revealed=false;$('night').value=n;$('title').textContent=nights[n].title;$('nightLabel').textContent='Night 0'+(n+1)+' / 05';say('The regulars are waiting. No timer, no score, no rush.');draw();}
$('night').innerHTML=nights.map((n,i)=>'<option value="'+i+'">'+(i+1)+'. '+n.title+'</option>').join('');
$('night').addEventListener('change',e=>load(Number(e.target.value)));
$('cats').addEventListener('click',e=>{const b=e.target.closest('[data-cat]');if(!b)return;const id=Number(b.dataset.cat);selected=selected===id?null:id;draw();say(selected===null?'Cat selection cleared.':names[selected]+' selected. Choose a place.');$('cats').querySelector('[data-cat="'+id+'"]').focus();});
$('seats').addEventListener('click',e=>{const el=e.target.closest('[data-seat]');if(!el)return;const i=Number(el.dataset.seat);if(selected===null){if(board[i]===null){say('Pick a cat above, then choose a place.');return;}selected=board[i];board[i]=null;say(names[selected]+' is ready to move. Choose a place.');}else{const old=board.indexOf(selected),other=board[i];if(old!==-1)board[old]=other;board[i]=selected;selected=null;say('Table rearranged. Ring the bell when everyone looks settled.');}checked=false;solved=false;revealed=false;draw();$('seats').querySelector('[data-seat="'+i+'"]').focus();});
$('check').addEventListener('click',()=>{checked=true;solved=board.every(c=>c!==null)&&nights[current].clues.every(c=>meets(board,c));if(solved){if(!revealed)completed.add(current);say(revealed?'The shown arrangement fits every clue. Try another evening on your own.':completed.size===5?'All five evenings solved! Four contented cats. One very accomplished maître d’.':'A chorus of purrs. Every clue fits. Supper is served!');}else say(board.includes(null)?'Someone is still waiting for a place. Seat all four cats, then try the bell.':'Not quite. The shaded notes need another look; the ticked notes already fit.');draw();});
$('hint').addEventListener('click',()=>{const i=nights[current].clues.findIndex(c=>!meets(board,c));if(i<0){say('All the notes fit. Time to ring the bell!');return;}$('clues').querySelectorAll('li').forEach(el=>el.classList.remove('hinted'));$('clue'+i).classList.add('hinted');say('Try the outlined note: '+nights[current].clues[i][3]+' Count places from the window on the left.');});
$('reset').addEventListener('click',()=>load(current));
$('next').addEventListener('click',()=>load(Math.min(4,current+1)));
$('reveal').addEventListener('click',()=>{board=solution(current)[0];selected=null;revealed=true;checked=true;solved=true;draw();say('Arrangement shown: '+board.map(i=>names[i]).join(' → ')+'. This evening is not added to your solved count. Clear the table to try it yourself.');});
load(0);
</script></body></html>
